//! Windows only: embed the icon in the exe, where Explorer, shortcuts and
//! the taskbar look for it. macOS and Linux read theirs from the app bundle
//! and the .desktop file instead (see the README).

fn main() {
    println!("cargo::rerun-if-changed=assets/ripbi.rc");
    println!("cargo::rerun-if-changed=assets/ripbi.ico");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }
    // Generated by brand.rs's tests, which need this crate to build first.
    if !std::path::Path::new("assets/ripbi.ico").exists() {
        println!("cargo::warning=assets/ripbi.ico is missing; the exe has no icon");
        return;
    }
    embed_resource::compile("assets/ripbi.rc", embed_resource::NONE)
        .manifest_optional()
        .unwrap();
}
